mapper.select:
select goodsid as goodsId, goodsname as name, cardnum as amount, goodsprice*100 as price, goodscreatetime as createDate, goodsstatus as status, category_type as categoryType, goodscreateperson as remark, photo as photo from ims_tpgoods WHERE goodsstatus = #{status}
AND category_type=#{type}
ORDER BY goodsId
